// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. Set up: owner (msg.sender) already is the deployer (this contract).
        // 2. Call sendMoney with a nonzero value to trigger fallback (target is self with value 1 wei)
        vm.deal(address(this), 1 ether);
        // The target address can be any address; using a random EOA to avoid reentrancy issues.
        address target = address(0x1234);
        vm.deal(target, 0);
        c.sendMoney{value: 1}(target, 1);
        // 3. Assert: depositsCount should be 1 for the correct contract, 0 for the buggy one.
        assertTrue(c.depositsCount() == 1, "depositsCount should be 1 after a payable fallback call");
    }
}

