}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // set up: fund the contract so it has 1 ether, then make owner send 1 ether back to itself via sendMoney
        vm.deal(address(c), 1 ether);
        // owner is the test contract (msg.sender in setUp), so prank as owner
        vm.prank(c.owner());
        // _target = address(c) and _value = 1 ether triggers a call that goes to fallback -> depositsCount++, but transfer only forwards 2300 gas which is enough for depositCount++ (unlike the reference call that forwards all gas)
        // The difference: reference (call) succeeds without revert, bug (transfer) also succeeds; after both, depositsCount increments
        // But we need a divergence: in the reference, the call to self forwards all gas and executes the fallback, incrementing depositsCount. In the buggy version, transfer also forwards 2300 gas which is enough for the fallback to increment depositsCount.
        // This scenario does NOT cause a revert difference because transfer forwards enough gas.
        // To force a revert difference we need a scenario where the fallback uses more than 2300 gas.
        // Let's instead make the contract call itself with a value that causes the fallback to revert due to out-of-gas when using transfer, but succeed when using call.
        // However, a simple increment of a uint uses very little gas. So we need the fallback to do more.
        // Since we cannot modify the fallback (it just increments), the gas consumption is minimal. Thus both call and transfer will succeed and depositsCount will increment in both.
        // So the original difference proposition "P.sendMoney() != M.sendMoney()" is not about a state variable named sendMoney (that doesn't exist), but about the effect after sendMoney call.
        // Actually the problem statement says "the value of state variable `sendMoney` differs: `P.sendMoney() != M.sendMoney()`". That suggests there is a state variable named sendMoney? No, sendMoney is a function. So likely a typo: they mean state variable `depositsCount` or `owner`? Let's assume they meant `depositsCount` because the fallback increments it.
        // In the reference, a call to sendMoney with target = address(c) triggers the fallback via call which forwards all gas, so depositsCount increments. In the buggy version, transfer only forwards 2300 gas, which is enough for the fallback, so depositsCount also increments. So no divergence.
        // To make the fallback consume more gas, we need the contract to have a more expensive fallback, but we can't modify it.
        // So the only way to force a revert difference is if the fallback fails for some other reason. Since the fallback only increments a uint, it won't revert under normal conditions.
        // Therefore the correct scenario is: sendMoney to an address that is not payable? But the reference uses .call which works with any address, while bug uses .transfer which requires payable. But the bug version casts to payable(_target), so it works with any address. So no difference.
        // The real difference: the reference uses low-level call which can reenter, the bug uses transfer which cannot reenter. If the fallback itself tries to call sendMoney again, that reentrancy could cause state changes. But the fallback only increments, not reenter.
        // Let's actually re-read the difference: "after a call to `sendMoney(...)` completes, the value of state variable `sendMoney` differs". There is no state variable sendMoney, but maybe they meant `depositsCount`. Under that interpretation, pick a scenario where the call to self via sendMoney fails due to gas in transfer but succeeds in call. But a simple increment succeeds with 2300 gas.
        // To cause a revert, the fallback would need to do a storage write that costs more than 2300 gas? Actually SLOAD and SSTORE cost 2100/5000 respectively. An increment (SLOAD + SSTORE) costs ~5000 gas, which exceeds 2300. So the fallback (depositsCount++) when called via transfer will revert due to out-of-gas, because transfer only forwards 2300 gas. In the reference, call forwards all gas, so it succeeds.
        // Perfect! So:
        // - Send exactly 1 wei to the contract via fallback using vm.deal and a direct call? No, we need sendMoney to self.
        // Step: fund contract with at least 1 wei, then call c.sendMoney(address(c), amount) with amount = 1.
        // The fallback does depositsCount++ which costs >2300 gas (SLOAD + SSTORE + increment). So transfer will revert, call will succeed.
        vm.deal(address(c), 1);
        vm.prank(c.owner());
        // In both reference and bug, the sendMoney call will send 1 wei to itself.
        // We need to capture whether the call reverted.
        bool ok;
        try c.sendMoney(address(c), 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference (call), the sendMoney succeeds and depositsCount becomes 1.
        // In bug (transfer), the sendMoney reverts because fallback runs out of gas, so depositsCount remains 0.
        // So after the attempt, we check depositsCount.
        // The reference has depositsCount == 1, bug has depositsCount == 0.
        assertTrue(c.depositsCount() == 1, "depositsCount should be 1 in reference");
    }
}
